import { createMemoryHistory } from "@tanstack/react-router";
import { scopeProjectRef, scopeThreadRef } from "@t3tools/client-runtime/environment";
import { ThreadId } from "@t3tools/contracts";
import { DEFAULT_CLIENT_SETTINGS } from "@t3tools/contracts/settings";
import type * as Context from "effect/Context";
import { expect, it, vi } from "vite-plus/test";
import { page } from "vite-plus/test/browser";

import { AppRoot } from "~/AppRoot";
import { DraftId, useComposerDraftStore } from "~/composerDraftStore";
import { __setClientSettingsForTests } from "~/hooks/useSettings";
import { getRouter } from "~/router";
import {
  ENVIRONMENT_ID,
  PROJECT_ID,
  installFakeEnvironment,
  threadWithHistory,
  type FakeDriver,
} from "../../test/fakeEnvironment";
import "~/index.css";
import { useTerminalUiStateStore } from "~/terminalUiStateStore";
import { render } from "../../test/render";

// The socket is the only fake layer; see test/appScenarios.renders.tsx.
vi.mock("../../../../packages/client-runtime/src/connection/driver.ts", async (importOriginal) => {
  const [actual, { fakeDriver }, Layer] = await Promise.all([
    importOriginal<{ readonly ConnectionDriver: Context.Key<unknown, FakeDriver> }>(),
    import("../../test/fakeEnvironment"),
    import("effect/Layer"),
  ]);
  return { ...actual, layer: Layer.succeed(actual.ConnectionDriver, fakeDriver) };
});

vi.mock(import("~/rpc/requestLatencyState"), async (original) => ({
  ...(await original()),
  trackRpcRequestSent: () => {},
}));

it("a new draft does not load its reserved thread before the server lists it", async () => {
  using _environment = installFakeEnvironment([]);
  using fetchSpy = vi.spyOn(globalThis, "fetch");
  __setClientSettingsForTests({
    ...DEFAULT_CLIENT_SETTINGS,
    onboardingCompletedAt: "2026-01-01T00:00:00.000Z",
  });
  const draftId = DraftId.make("draft-27443");
  const threadId = ThreadId.make("thread-27443");
  useComposerDraftStore
    .getState()
    .setProjectDraftThreadId(scopeProjectRef(ENVIRONMENT_ID, PROJECT_ID), draftId, { threadId });

  const router = getRouter(createMemoryHistory({ initialEntries: [`/draft/${draftId}`] }));
  await router.load();
  await using _app = await render(<AppRoot router={router} />, {
    // AppRoot brings its own router.
    router: false,
  });
  await expect.element(page.getByTestId("composer-editor")).toBeVisible();
  // The shell snapshot has arrived once the sidebar lists the project, so the connection is up.
  await expect.element(page.getByText("render", { exact: true }).first()).toBeVisible();

  const threadRequests = fetchSpy.mock.calls
    .map(([input]) => String(input instanceof Request ? input.url : input))
    .filter((url) => url.includes(`/api/orchestration/threads/${threadId}/`));
  // A 404 here marks the thread deleted, and the view never loads it once the send creates it.
  expect(threadRequests).toEqual([]);
});

for (const focus of ["composer", "terminal", "modal"] as const) {
  it(`V5 restores ${focus} focus through actual A B A navigation`, async () => {
    await page.viewport(1400, 900);
    const a = threadWithHistory(`v5-${focus}-a`, 1);
    const b = threadWithHistory(`v5-${focus}-b`, 1);
    using _environment = installFakeEnvironment([a, b]);
    __setClientSettingsForTests({
      ...DEFAULT_CLIENT_SETTINGS,
      onboardingCompletedAt: "2026-01-01T00:00:00.000Z",
    });
    useTerminalUiStateStore.getState().setTerminalOpen(scopeThreadRef(ENVIRONMENT_ID, a.id), true);
    const router = getRouter(createMemoryHistory({ initialEntries: [`/${ENVIRONMENT_ID}/${a.id}`] }));
    await router.load();
    const container = document.createElement("div");
    container.style.cssText = "height:900px;width:1400px";
    // AppRoot owns the router, as the production entry point does.
    await using _app = await render(<AppRoot router={router} />, { container, router: false });
    const composer = page.getByTestId("composer-editor");
    await vi.waitFor(() => expect(composer.query()).not.toBeNull());
    await expect.element(composer).toBeVisible();
    await vi.waitFor(() => expect(document.querySelector('[data-terminal-owner="drawer"] [tabindex="-1"]')).not.toBeNull());
    const terminal = page.elementLocator(document.querySelector<HTMLElement>('[data-terminal-owner="drawer"] [tabindex="-1"]')!);
    await expect.element(terminal).toBeVisible();
    if (focus === "terminal") {
      terminal.element().focus();
      expect(document.activeElement?.closest('[data-terminal-owner="drawer"]')).not.toBeNull();
    } else {
      await composer.click();
      await expect.element(composer).toHaveFocus();
    }
    await page.getByText(b.title, { exact: true }).nth(1).click();
    await expect.element(page.getByText(`Answer 0 for ${b.id}.`, { exact: false })).toBeVisible();
    if (focus === "modal") {
      await page.getByText(a.title, { exact: true }).nth(1).click();
      const dialog = document.createElement("dialog");
      const input = document.createElement("input");
      dialog.append(input);
      document.body.append(dialog);
      using _dialog = { [Symbol.dispose]: () => dialog.remove() };
      dialog.showModal();
      input.focus();
      await expect.element(page.getByText(`Answer 0 for ${a.id}.`, { exact: false })).toBeVisible();
      expect(document.activeElement).toBe(input);
    } else {
      await page.getByText(a.title, { exact: true }).nth(1).click();
      await expect.element(page.getByText(`Answer 0 for ${a.id}.`, { exact: false })).toBeVisible();
      if (focus === "composer") await expect.element(composer).toHaveFocus();
      else await vi.waitFor(() => expect(document.activeElement?.closest('[data-terminal-owner="drawer"]')).not.toBeNull());
    }
  });
}
